  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ─── Enums ───────────────────────────────────────────────────────────────────\n\nenum BoardStatus {\n  ACTIVE\n  ARCHIVED\n  CLOSED\n}\n\nenum TaskStatus {\n  TODO\n  IN_PROGRESS\n  IN_REVIEW\n  DONE\n  CANCELLED\n}\n\nenum PermissionType {\n  ALLOW\n  DENY\n}\n\n// ─── Models ──────────────────────────────────────────────────────────────────\n\nmodel User {\n  id           String   @id @default(uuid()) @db.Uuid\n  display_name String\n  username     String\n  email        String?\n  phone_number String?\n  password     String\n  role         Int\n  created_at   DateTime @default(now())\n  updated_at   DateTime @updatedAt\n\n  user_groups   UserGroup[]\n  user_teams    UserTeam[]\n  task_members  TaskMember[]\n  task_history  TaskHistory[]\n  task_comments TaskComment[]\n  created_tasks Task[]        @relation(\"TaskCreatedBy\")\n\n  @@map(\"users\")\n}\n\nmodel Team {\n  id         String   @id @default(uuid()) @db.Uuid\n  name       String\n  created_at DateTime @default(now())\n  updated_at DateTime @updatedAt\n\n  user_teams UserTeam[]\n  boards     Board[]\n  groups     Group[]\n\n  @@map(\"teams\")\n}\n\nmodel Group {\n  id          String  @id @default(uuid()) @db.Uuid\n  team_id     String  @db.Uuid\n  all_members Boolean @default(false)\n\n  team        Team         @relation(fields: [team_id], references: [id])\n  user_groups UserGroup[]\n  permissions Permission[]\n\n  @@map(\"groups\")\n}\n\nmodel UserTeam {\n  user_id    String   @db.Uuid\n  team_id    String   @db.Uuid\n  role       Int\n  created_at DateTime @default(now())\n  updated_at DateTime @updatedAt\n\n  user User @relation(fields: [user_id], references: [id])\n  team Team @relation(fields: [team_id], references: [id])\n\n  @@id([user_id, team_id])\n  @@map(\"user_teams\")\n}\n\nmodel UserGroup {\n  user_id    String   @db.Uuid\n  group_id   String   @db.Uuid\n  created_at DateTime @default(now())\n  updated_at DateTime @updatedAt\n\n  user  User  @relation(fields: [user_id], references: [id])\n  group Group @relation(fields: [group_id], references: [id])\n\n  @@id([user_id, group_id])\n  @@map(\"user_groups\")\n}\n\nmodel Board {\n  id         String      @id @default(uuid()) @db.Uuid\n  name       String\n  team_id    String      @db.Uuid\n  status     BoardStatus\n  created_at DateTime    @default(now())\n  updated_at DateTime    @updatedAt\n\n  team       Team        @relation(fields: [team_id], references: [id])\n  lists      List[]\n  checklists Checklist[]\n  labels     Label[]\n\n  @@map(\"boards\")\n}\n\nmodel List {\n  id         String   @id @default(uuid()) @db.Uuid\n  name       String\n  board_id   String   @db.Uuid\n  created_at DateTime @default(now())\n  updated_at DateTime @updatedAt\n\n  board Board  @relation(fields: [board_id], references: [id])\n  tasks Task[]\n\n  @@map(\"lists\")\n}\n\nmodel Task {\n  id           String     @id @default(uuid()) @db.Uuid\n  list_id      String     @db.Uuid\n  name         String\n  description  String\n  checklist_id String?    @db.Uuid\n  created_by   String     @db.Uuid\n  start_date   DateTime?\n  end_date     DateTime?\n  status       TaskStatus\n  position     Int\n  created_at   DateTime   @default(now())\n  updated_at   DateTime   @updatedAt\n\n  list             List             @relation(fields: [list_id], references: [id])\n  checklist        Checklist?       @relation(fields: [checklist_id], references: [id])\n  creator          User             @relation(\"TaskCreatedBy\", fields: [created_by], references: [id])\n  task_members     TaskMember[]\n  task_attachments TaskAttachment[]\n  task_history     TaskHistory[]\n  task_labels      TaskLabel[]\n  task_comments    TaskComment[]\n\n  @@map(\"tasks\")\n}\n\nmodel TaskMember {\n  user_id String @db.Uuid\n  task_id String @db.Uuid\n  role    Int?\n\n  user User @relation(fields: [user_id], references: [id])\n  task Task @relation(fields: [task_id], references: [id])\n\n  @@id([user_id, task_id])\n  @@map(\"task_members\")\n}\n\nmodel TaskAttachment {\n  task_id       String @db.Uuid\n  attachment_id String @db.Uuid\n\n  task       Task       @relation(fields: [task_id], references: [id])\n  attachment Attachment @relation(fields: [attachment_id], references: [id])\n\n  @@id([task_id, attachment_id])\n  @@map(\"task_attachments\")\n}\n\nmodel TaskComment {\n  id                String   @id @default(uuid()) @db.Uuid\n  task_id           String   @db.Uuid\n  user_id           String   @db.Uuid\n  parent_comment_id String?  @db.Uuid\n  content           String\n  is_edited         Boolean  @default(false)\n  created_at        DateTime @default(now())\n  updated_at        DateTime @updatedAt\n\n  task           Task          @relation(fields: [task_id], references: [id])\n  user           User          @relation(fields: [user_id], references: [id])\n  parent_comment TaskComment?  @relation(\"CommentReplies\", fields: [parent_comment_id], references: [id])\n  replies        TaskComment[] @relation(\"CommentReplies\")\n\n  @@map(\"task_comments\")\n}\n\nmodel TaskHistory {\n  id       String @id @default(uuid()) @db.Uuid\n  task_id  String @db.Uuid\n  user_id  String @db.Uuid\n  activity Json\n  type     String\n\n  task Task @relation(fields: [task_id], references: [id])\n  user User @relation(fields: [user_id], references: [id])\n\n  @@map(\"task_history\")\n}\n\nmodel Checklist {\n  id         String   @id @default(uuid()) @db.Uuid\n  board_id   String   @db.Uuid\n  created_at DateTime @default(now())\n  updated_at DateTime @updatedAt\n\n  board           Board           @relation(fields: [board_id], references: [id])\n  checklist_items ChecklistItem[]\n  tasks           Task[]\n\n  @@map(\"checklists\")\n}\n\nmodel ChecklistItem {\n  id           String   @id @default(uuid()) @db.Uuid\n  checklist_id String   @db.Uuid\n  name         String\n  status       Boolean  @default(false)\n  created_at   DateTime @default(now())\n  updated_at   DateTime @updatedAt\n\n  checklist Checklist @relation(fields: [checklist_id], references: [id])\n\n  @@map(\"checklist_items\")\n}\n\nmodel Label {\n  id         String   @id @default(uuid()) @db.Uuid\n  name       String\n  color      String\n  board_id   String   @db.Uuid\n  created_at DateTime @default(now())\n  updated_at DateTime @updatedAt\n\n  board       Board       @relation(fields: [board_id], references: [id])\n  task_labels TaskLabel[]\n\n  @@map(\"labels\")\n}\n\nmodel TaskLabel {\n  task_id    String   @db.Uuid\n  label_id   String   @db.Uuid\n  created_at DateTime @default(now())\n  updated_at DateTime @updatedAt\n\n  task  Task  @relation(fields: [task_id], references: [id])\n  label Label @relation(fields: [label_id], references: [id])\n\n  @@id([task_id, label_id])\n  @@map(\"task_labels\")\n}\n\nmodel Attachment {\n  id   String @id @default(uuid()) @db.Uuid\n  type String\n  name String\n  url  String\n\n  task_attachments TaskAttachment[]\n\n  @@map(\"attachments\")\n}\n\nmodel Permission {\n  id          String         @id @default(uuid()) @db.Uuid\n  action      String\n  type        PermissionType\n  priority    Int\n  description String?\n  group_id    String         @db.Uuid\n  scope_type  String?\n  scope_id    String?        @db.Uuid\n  created_at  DateTime       @default(now())\n  updated_at  DateTime       @updatedAt\n\n  group Group @relation(fields: [group_id], references: [id])\n\n  @@map(\"permissions\")\n}\n",
